"""Small dependency-free hospital operations dashboard.

Assignments are in-memory for this process; source CSV files are never changed.
"""
import json
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
from investigation import build_queue, public_status, ai_explain, load_csv

QUEUE = build_queue()
ALERTS = {a["id"]: a for a in QUEUE}
ASSIGNMENTS = {}
CAPABILITIES = {
    "Emergency": ["high_acuity_delay", "prolonged_wait"],
    "Radiology": ["delayed_urgent_test"],
    "Cardiology": ["delayed_urgent_test", "high_acuity_delay"],
    "Laboratory": ["delayed_urgent_test"],
    "General Medicine": ["prolonged_wait", "incomplete_record"],
    "Pediatrics": ["prolonged_wait", "high_acuity_delay"],
}
DEPARTMENTS = []
for row in load_csv("departments.csv"):
    name = row["department_name"]
    DEPARTMENTS.append({
        "id": row["department_id"], "name": name,
        "capacity": int(float(row["bed_count"])),
        "occupancy": 0,
        "capabilities": CAPABILITIES.get(name, ["prolonged_wait", "incomplete_record"]),
        "service_type": row["service_type"],
    })
ROOMS = {r["name"]: r for r in DEPARTMENTS}

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Hospital Operations | Investigation Queue</title>
<style>
:root{--bg:#f7f8fa;--surface:#fff;--line:#dfe3e8;--text:#20262d;--muted:#68727d;--blue:#2867a6;--blue-soft:#eef5fb;--red:#b42318;--amber:#9a6700;--green:#18794e;--radius:6px;font:13px Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}button,select{font:inherit}button{cursor:pointer}.topbar{height:68px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px}.brand{font-size:17px;font-weight:700;letter-spacing:-.2px}.brand small{font-size:11px;color:var(--muted);font-weight:400;margin-left:12px}.status{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.dot{width:7px;height:7px;border-radius:50%;background:var(--green)}.shell{max-width:1500px;margin:auto;padding:24px 28px}.headline{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.headline h1{font-size:22px;margin:0 0 4px;letter-spacing:-.4px}.headline p{margin:0;color:var(--muted)}.notice{font-size:11px;color:var(--muted);border:1px solid var(--line);background:#fff;padding:7px 10px;border-radius:4px}.dashboard{display:grid;grid-template-columns:300px minmax(400px,1fr) 350px;gap:16px;align-items:start}.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);min-width:0}.panel-head{padding:15px 16px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.panel-head h2{font-size:14px;margin:0}.panel-head span{color:var(--muted);font-size:11px}.controls{padding:12px 16px;border-bottom:1px solid var(--line);display:flex;gap:7px}.controls select{min-width:0;width:50%;padding:7px;border:1px solid var(--line);border-radius:4px;background:#fff;color:var(--text)}.queue{max-height:calc(100vh - 220px);overflow:auto;padding:8px}.queue-card{padding:12px;border:1px solid transparent;border-bottom-color:var(--line);cursor:pointer}.queue-card:hover{background:#fafcfe}.queue-card.selected{background:var(--blue-soft);border:1px solid #9dbdda;border-radius:4px}.qtop{display:flex;justify-content:space-between;gap:8px}.qid{font-weight:700}.category{font-size:11px;color:var(--muted);margin-top:4px}.reason{font-size:12px;margin:7px 0;color:#3f4851}.qmeta{display:flex;gap:10px;color:var(--muted);font-size:11px}.score{font-weight:700}.p-high{color:var(--red)}.p-med{color:var(--amber)}.p-low{color:var(--green)}.smallpill{font-size:10px;padding:2px 5px;border:1px solid var(--line);border-radius:3px;color:var(--muted)}.map{padding:16px}.floor{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:minmax(106px,1fr);gap:10px;position:relative;min-height:410px}.room{border:1px solid var(--line);background:#fbfcfd;border-radius:5px;padding:11px;position:relative;transition:border-color .2s,background .2s}.room.waiting{grid-column:span 2;background:#f3f5f7;border-style:dashed}.room.active{border-color:var(--blue);background:var(--blue-soft)}.room.arrival{animation:arrive .65s ease-out;border-color:var(--blue)}@keyframes arrive{0%{background:#d9eafa}100%{background:var(--blue-soft)}}.room h3{margin:0 0 8px;font-size:13px}.occupancy{font-size:20px;font-weight:700}.occupancy small{font-size:11px;color:var(--muted);font-weight:400}.capability{color:var(--muted);font-size:10px;line-height:1.4;margin-top:8px}.availability{position:absolute;right:10px;top:12px;width:7px;height:7px;border-radius:50%;background:var(--green)}.availability.full{background:var(--red)}.availability.limited{background:var(--amber)}.route-path{display:none;position:absolute;height:2px;background:var(--blue);z-index:3;transform-origin:left center}.route-path.go{display:block;animation:route .6s ease-out forwards}@keyframes route{from{transform:scaleX(0);opacity:.3}to{transform:scaleX(1);opacity:1}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition:none!important}}.rightcol{display:flex;flex-direction:column;gap:16px}.priority-groups{padding:12px 16px}.priority-group{border-bottom:1px solid var(--line);padding:8px 0}.priority-group:last-child{border:0}.priority-group h3{margin:0 0 6px;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.priority-row{display:flex;justify-content:space-between;padding:5px 0;font-size:11px;cursor:pointer}.detail{padding:16px}.detail h2{font-size:16px;margin:0 0 5px}.detail h3{font-size:12px;margin:18px 0 8px}.muted{color:var(--muted)}.metrics{display:flex;gap:6px;margin:13px 0}.metric{border:1px solid var(--line);border-radius:4px;padding:7px 9px;flex:1}.metric b{display:block;font-size:16px}.metric span{font-size:10px;color:var(--muted)}.evidence{display:grid;grid-template-columns:105px 1fr;gap:6px;border-top:1px solid #edf0f2;padding:7px 0;font-size:11px}.evidence b{color:var(--muted)}.breakdown{font-size:11px}.breakrow{margin:8px 0}.breakrow div{display:flex;justify-content:space-between}.bar{height:4px;background:#e8ebee;margin-top:4px}.bar i{display:block;height:100%;background:var(--blue)}.uncertainty{color:var(--amber);font-size:11px;line-height:1.5}.assignbox{border-top:1px solid var(--line);margin:16px -16px -16px;padding:14px 16px;background:#fafbfc}.assignbox label{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.assignbox select{width:100%;padding:8px;border:1px solid var(--line);border-radius:4px;background:#fff}.primary{width:100%;margin-top:8px;padding:9px;border:1px solid var(--blue);border-radius:4px;background:var(--blue);color:#fff;font-weight:600}.primary:disabled{background:#a8bacb;border-color:#a8bacb;cursor:not-allowed}.active-list{padding:10px 16px}.assignment{padding:8px 0;border-bottom:1px solid var(--line);font-size:11px}.assignment:last-child{border:0}.empty{padding:25px 14px;text-align:center;color:var(--muted);font-size:12px}.ai{margin-top:12px;padding:10px;border-left:3px solid var(--blue);background:var(--blue-soft);font-size:11px}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:#20262d;color:#fff;padding:10px 14px;border-radius:4px;font-size:12px;display:none}.toast.show{display:block}
</style></head><body>
<header class="topbar"><div class="brand">Hospital Operations <small>Investigation &amp; routing workspace</small></div><div class="status"><i class="dot"></i><span id="provider">Local evidence mode</span></div></header>
<main class="shell"><div class="headline"><div><h1>Patient flow overview</h1><p>Review operational alerts, verify evidence, and assign a destination.</p></div><div class="notice">Operational aid · not a clinical decision</div></div>
<div class="dashboard"><section class="panel"><div class="panel-head"><h2>Waiting queue</h2><span id="count">Loading</span></div><div class="controls"><select id="category" aria-label="Filter by alert category"><option value="">All categories</option></select><select id="sort" aria-label="Sort queue"><option value="priority">Priority</option><option value="impact">Impact</option><option value="confidence">Confidence</option></select></div><div id="queue" class="queue"></div></section>
<section class="panel"><div class="panel-head"><h2>Room assignment map</h2><span>Capacity &amp; capability</span></div><div class="map"><div id="floor" class="floor"></div><div class="muted" style="font-size:11px;margin-top:10px">Suggested destinations are derived from recorded triage and test signals. Confirm assignments manually.</div></div></section>
<div class="rightcol"><section class="panel"><div class="panel-head"><h2>Priorities</h2><span>Top waiting alerts</span></div><div id="priorities" class="priority-groups"></div></section><section class="panel"><div class="panel-head"><h2>Selected alert</h2><span id="selectedLabel">None selected</span></div><div id="detail" class="detail"><div class="empty">Select an alert from the queue.</div></div></section><section class="panel"><div class="panel-head"><h2>Active assignments</h2><span id="assignedCount">0</span></div><div id="assignments" class="active-list"><div class="empty">No confirmed assignments.</div></div></section></div></div></main><div id="toast" class="toast" role="status"></div>
<script>
let alerts=[],rooms=[],assignments=[],selected=null,routeFlash=null;const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function priorityClass(x){return x>=70?'p-high':x>=45?'p-med':'p-low'}function roomFor(name){return rooms.find(r=>r.name===name)}
function renderQueue(){let cat=$('category').value,sort=$('sort').value,a=alerts.filter(x=>!cat||x.category===cat).sort((x,y)=>y[sort]-x[sort]||x.id.localeCompare(y.id));$('count').textContent=`${a.length} waiting`;$('queue').innerHTML=a.length?a.map(x=>`<article class="queue-card ${selected?.id===x.id?'selected':''}" tabindex="0" onclick="selectAlert('${x.id}')" onkeydown="if(event.key==='Enter')selectAlert('${x.id}')"><div class=qtop><span class=qid>${esc(x.id)}</span><span class="score ${priorityClass(x.priority)}">${x.priority}</span></div><div class=category>${esc(x.title)} · ${esc(x.context.department)}</div><div class=reason>${esc(x.reason)}</div><div class=qmeta><span>Triage ${esc(x.evidence.find(e=>e.field==='triage_level')?.value||'—')}</span><span>Wait ${esc(x.evidence.find(e=>e.field==='wait_minutes')?.value||'—')} min</span><span>I ${x.impact}</span><span>C ${x.confidence}</span><span class=${x.anomaly_flagged?'p-high':''}>A ${x.anomaly_score}</span></div></article>`).join(''):'<div class=empty>No alerts match this filter.</div>'}
function renderRooms(){let floor=$('floor');floor.innerHTML='<div class="room waiting" id="waiting"><span class=availability></span><h3>Waiting area</h3><div class=occupancy>'+alerts.length+' <small>waiting alerts</small></div><div class=capability>Incoming operational alerts</div></div>';rooms.forEach(r=>{let used=assignments.filter(a=>a.destination===r.name).length,ratio=used/r.capacity,cls=ratio>=1?'full':ratio>.7?'limited':'';floor.insertAdjacentHTML('beforeend',`<div class="room ${selected?.routing.destination===r.name?'active':''}" id="room-${esc(r.id)}"><span class="availability ${cls}"></span><h3>${esc(r.name)}</h3><div class=occupancy>${used} <small>/ ${r.capacity} occupied</small></div><div class=capability><b>Handles:</b> ${r.capabilities.map(esc).join(', ')}</div></div>`)});if(routeFlash){let target=rooms.find(r=>r.id===routeFlash);if(target)floor.insertAdjacentHTML('beforeend',`<div class="route-path go" style="left:24%;top:38%;width:58%" aria-label="Route to ${esc(target.name)}"></div>`)}}
function renderPriorities(){let html='';[['High',a=>a.priority>=70,'p-high'],['Medium',a=>a.priority>=45&&a.priority<70,'p-med'],['Low',a=>a.priority<45,'p-low']].forEach(([name,fn,cl])=>{let list=alerts.filter(fn).slice(0,4);html+=`<div class=priority-group><h3 class=${cl}>${name} priority <span>(${list.length})</span></h3>${list.length?list.map(x=>`<div class=priority-row onclick="selectAlert('${x.id}')"><span>${esc(x.id)} · ${esc(x.title)}</span><b>${x.priority}</b></div>`).join(''):'<span class=muted>No waiting alerts</span>'}</div>`});$('priorities').innerHTML=html}
function selectAlert(id){selected=alerts.find(x=>x.id===id);renderQueue();renderRooms();renderDetail()}
function renderDetail(){if(!selected){$('detail').innerHTML='<div class=empty>Select an alert from the queue.</div>';return}let x=selected,compatible=rooms.filter(r=>r.capabilities.includes(x.category)).sort((a,b)=>(b.capacity-b.occupancy)-(a.capacity-a.occupancy));let choices=[...new Map([...(compatible.length?compatible:rooms).map(r=>[r.name,r])]).values()];$('selectedLabel').textContent=x.id;$('detail').innerHTML=`<h2>${esc(x.title)}</h2><div class=muted>${esc(x.id)} · ${esc(x.context.department)} · ${esc(x.context.arrival_time||'No timestamp')}</div><div class=metrics><div class=metric><b class=${priorityClass(x.priority)}>${x.priority}</b><span>Priority</span></div><div class=metric><b>${x.impact}</b><span>Impact</span></div><div class=metric><b>${x.confidence}</b><span>Confidence</span></div><div class=metric><b>${x.anomaly_score}</b><span>ML anomaly${x.anomaly_flagged?' · flagged':''}</span></div></div><p class=muted style="font-size:11px">The anomaly score measures unusualness relative to the training encounters. It is not a probability, diagnosis, or measure of harm.</p><h3>Evidence</h3>${x.evidence.map(e=>`<div class=evidence><b>${esc(e.field)}</b><span>${esc(e.value)} <span class=muted>${esc(e.source)}</span></span></div>`).join('')}<h3>Model feature values</h3><div class=evidence>${Object.entries(x.model_features||{}).map(([k,v])=>`<b>${esc(k)}</b><span>${esc(v)}</span>`).join('')}</div><h3>Uncertainty</h3><div class=uncertainty>${x.uncertainty.map(esc).join('<br>')}</div><h3>Score breakdown</h3><div class=breakdown>${x.score_breakdown.map(s=>`<div class=breakrow><div><span>${esc(s.component)}</span><span>${s.contribution} (${s.weight})</span></div><div class=bar><i style="width:${s.value}%"></i></div></div>`).join('')}<div class=breakrow><div><span>ML anomaly signal</span><span>${x.anomaly_score} × 30%</span></div><div class=bar><i style="width:${x.anomaly_score}%"></i></div></div></div><p class=muted style="font-size:11px">Priority = 40% impact + 25% evidence confidence + 30% ML anomaly signal + 5% high-impact uncertainty value.</p><div class=assignbox><label for=destination>Suggested destination · ${esc(x.routing.reason)}</label><select id=destination>${choices.map(r=>`<option value="${esc(r.name)}" ${r.name===x.routing.destination?'selected':''}>${esc(r.name)} · ${r.capacity-r.occupancy} available · ${esc(r.capabilities.join(', '))}</option>`).join('')}</select><button class=primary onclick="assign()">Confirm assignment</button><div class=muted style="margin-top:6px;font-size:10px">${esc(x.routing.disclaimer)} Assignment requires confirmation.</div></div><button style="margin-top:14px;padding:7px;border:1px solid var(--line);background:#fff;border-radius:4px" onclick="askAI()">Generate AI explanation</button><div id=ai></div>`}
async function assign(){let destination=$('destination').value,r=roomFor(destination);if(!selected||!r)return;if(r.capacity-r.occupancy<=0){toast('That destination is at capacity. Choose another room.');return}let res=await fetch('/api/assign',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({alert_id:selected.id,destination})}),data=await res.json();if(!res.ok){toast(data.error||'Assignment failed');return}assignments=data.assignments;alerts=alerts.filter(x=>x.id!==selected.id);routeFlash=r.id;let target=$('room-'+r.id);if(target){target.classList.add('arrival');setTimeout(()=>target.classList.remove('arrival'),800)}toast(`${selected.id} assigned to ${destination}`);selected=null;renderAll();setTimeout(()=>{routeFlash=null;renderRooms()},900)}
async function askAI(){$('ai').innerHTML='<div class=ai>Loading provider explanation…</div>';let r=await fetch('/api/explain?id='+encodeURIComponent(selected.id),{method:'POST'}),x=await r.json();$('ai').innerHTML=`<div class=ai><b>${x.status==='ai'?'AI explanation':'Local evidence explanation'}</b><p>${esc(x.summary)}</p>${x.next_step?'<p><b>Next step:</b> '+esc(x.next_step)+'</p>':''}</div>`}
function renderAssignments(){$('assignedCount').textContent=assignments.length; $('assignments').innerHTML=assignments.length?assignments.slice().reverse().map(a=>`<div class=assignment><b>${esc(a.alert_id)}</b> → ${esc(a.destination)}<br><span class=muted>${esc(a.assigned_at)}</span></div>`).join(''):'<div class=empty>No confirmed assignments.</div>'}
function renderAll(){renderQueue();renderRooms();renderPriorities();renderAssignments();renderDetail()}function toast(s){$('toast').textContent=s;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2400)}
async function init(){let d=await (await fetch('/api/state')).json();alerts=d.alerts;rooms=d.rooms;assignments=d.assignments;let cats=[...new Set(alerts.map(x=>x.category))];cats.forEach(c=>$('category').insertAdjacentHTML('beforeend',`<option value="${esc(c)}">${esc(c.replaceAll('_',' '))}</option>`));$('provider').textContent=d.provider.ai_configured?d.provider.provider+' explanations available':'Local evidence mode';renderAll()}$('category').onchange=renderQueue;$('sort').onchange=renderQueue;init();
</script></body></html>'''


def snapshot():
    rooms = []
    for r in DEPARTMENTS:
        copy = dict(r)
        copy["occupancy"] = sum(a["destination"] == r["name"] for a in ASSIGNMENTS.values())
        rooms.append(copy)
    return {"alerts": [a for a in QUEUE if a["id"] not in ASSIGNMENTS], "rooms": rooms, "assignments": list(ASSIGNMENTS.values()), "provider": public_status()}

class Handler(BaseHTTPRequestHandler):
    def send(self, data, code=200, typ="application/json"):
        raw = data.encode() if isinstance(data, str) else data
        self.send_response(code); self.send_header("Content-Type", typ); self.send_header("Content-Length", str(len(raw))); self.end_headers(); self.wfile.write(raw)
    def body(self):
        n = int(self.headers.get("Content-Length", 0)); return json.loads(self.rfile.read(n) or b"{}")
    def do_GET(self):
        path = urlparse(self.path).path
        if path == "/": return self.send(HTML, typ="text/html")
        if path == "/api/state": return self.send(json.dumps(snapshot()))
        if path == "/api/status": return self.send(json.dumps(public_status()))
        self.send(json.dumps({"error":"not found"}), 404)
    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path == "/api/explain":
            alert = ALERTS.get(parse_qs(parsed.query).get("id", [""])[0])
            if not alert: return self.send(json.dumps({"error":"unknown alert"}), 404)
            return self.send(json.dumps(ai_explain(alert)))
        if parsed.path == "/api/assign":
            data = self.body(); alert_id, destination = data.get("alert_id"), data.get("destination")
            if alert_id not in ALERTS or alert_id in ASSIGNMENTS: return self.send(json.dumps({"error":"Alert is no longer waiting"}), 409)
            room = ROOMS.get(destination)
            if not room: return self.send(json.dumps({"error":"Unknown destination"}), 400)
            occupancy = sum(a["destination"] == destination for a in ASSIGNMENTS.values())
            if occupancy >= room["capacity"]: return self.send(json.dumps({"error":"Destination is at capacity"}), 409)
            ASSIGNMENTS[alert_id] = {"alert_id": alert_id, "destination": destination, "assigned_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")}
            return self.send(json.dumps({"ok": True, "assignments": list(ASSIGNMENTS.values())}))
        self.send(json.dumps({"error":"not found"}), 404)
    def log_message(self, *_): pass

if __name__ == "__main__":
    print(f"Hospital operations dashboard: http://localhost:8000 ({len(QUEUE)} alerts)")
    HTTPServer(("localhost", 8000), Handler).serve_forever()
